SELECT * FROM portfolio WHERE user_id = #{userId} AND pf_id > 0
AND (title LIKE CONCAT('%', #{search}, '%') OR content LIKE CONCAT('%', #{search}, '%'))
ORDER BY created_at DESC LIMIT #{limit} OFFSET #{offset}

SELECT *
FROM portfolio
WHERE user_id = #{userId} AND pf_id = #{pfId}

mapper.update:
UPDATE portfolio
SET title = #{title},
    content = #{content}
WHERE user_id = #{userId} AND pf_id = #{pfId}

mapper.select:
